#!/bin/sh
# Generated by compost. Creates Temporal's tables, or updates them to the
# version of this image; does nothing when they are current. The database
# links set the variables.
set -eu
schema=/etc/temporal/schema/postgresql/v12
# setup <schema> <host> <port> <user> <password> <database>
setup() {
  export SQL_PASSWORD="$5"
  echo "Database $6:"
  temporal-sql-tool --plugin postgres12 --ep "$2" -p "$3" -u "$4" --db "$6" setup-schema -v 0.0
  temporal-sql-tool --plugin postgres12 --ep "$2" -p "$3" -u "$4" --db "$6" update-schema -d "$schema/$1/versioned"
}
setup temporal "$POSTGRES_SEEDS" "$DB_PORT" "$POSTGRES_USER" "$POSTGRES_PWD" "$DBNAME"
setup visibility "$VISIBILITY_POSTGRES_SEEDS" "$VISIBILITY_DB_PORT" "$VISIBILITY_POSTGRES_USER" "$VISIBILITY_POSTGRES_PWD" "$VISIBILITY_DBNAME"
